        return 0;
    }

    const uint8_t *separator = memchr(query, 61, len_query);
    size_t len_key = separator ? (size_t)(separator - query) : (size_t)len_query;
    size_t len_value = separator ? (size_t)(len_query - len_key - 1) : 0;

    if ((len_key + 1 > key_len) || (len_value + 1 > value_len)) {
        return -E2BIG;
    }

    memcpy(key, query, len_key);
    key[len_key] = 0;

